# State + event loading.
app=app.replace("templates:[], signatures:[], settings:null,", "templates:[], signatures:[], settings:null, events:[],", 1)
app=app.replace("const [m,a,l,ml,c,t,sg,s,f]=await Promise.all([", "const [m,a,l,ml,c,t,sg,s,f,ev]=await Promise.all([", 1)
app=app.replace("    supabase.from('frankiflow_mail_filters').select('*').order('created_at')\n  ]);", "    supabase.from('frankiflow_mail_filters').select('*').order('created_at'),\n    supabase.from('frankiflow_mail_events').select('*').order('start_at',{ascending:true})\n  ]);", 1)
app=app.replace("const err=[m,a,l,ml,c,t,sg,s,f].find(x=>x.error)?.error;", "const err=[m,a,l,ml,c,t,sg,s,f,ev].find(x=>x.error)?.error;", 1)
app=app.replace("state.settings=s.data||null;state.filters=f.data||[];", "state.settings=s.data||null;state.filters=f.data||[];state.events=ev.data||[];", 1)

# Empty composer must not create a signature-only draft.
old_save="async function saveDraft(){if(!state.composer)return;const d=composerData();if(!d)return;if(!state.composer.draftId&&!d.to.trim()&&!d.cc.trim()&&!d.bcc.trim()&&!d.subject.trim()&&!d.text.trim()){state.composer.el.querySelector('#draftStatus').textContent='Autosave on';return;}"
new_save="function composerHasMeaningfulContent(d){if(!d)return false;if(d.to.trim()||d.cc.trim()||d.bcc.trim()||d.subject.trim()||state.composer?.files?.length||state.composer?.meeting)return true;const box=document.createElement('div');box.innerHTML=d.html||'';box.querySelectorAll('.signature[data-ff-signature]').forEach(x=>x.remove());return Boolean(stripHtml(box.innerHTML).trim());}\nasync function saveDraft(){if(!state.composer)return;const d=composerData();if(!d)return;if(!state.composer.draftId&&!composerHasMeaningfulContent(d)){state.composer.el.querySelector('#draftStatus').textContent='Autosave on';return;}"
if old_save not in app: raise SystemExit('saveDraft marker changed')
app=app.replace(old_save,new_save,1)
old_close="async function closeComposer(){if(!state.composer)return;await saveDraft();state.composer?.el.remove();state.composer=null;}"
new_close="async function closeComposer(){if(!state.composer)return;clearTimeout(state.composer.saveTimer);const d=composerData();if(!state.composer.draftId&&!composerHasMeaningfulContent(d)){state.composer.el.remove();state.composer=null;return;}await saveDraft();state.composer?.el.remove();state.composer=null;}"
if old_close not in app: raise SystemExit('closeComposer marker changed')
app=app.replace(old_close,new_close,1)

# Expansion icon only in quick reply.
app=app.replace("<button class=\"btn\" id=\"replyCompose\">${icon('open_in_full')} Full composer</button>", "<button class=\"icon-btn\" id=\"replyCompose\" title=\"Full composer\" aria-label=\"Full composer\">${icon('open_in_full')}</button>", 1)

# Replace the basic meeting invitation block with the Outlook-style event system.
start=app.find('function localDateTimeValue(date)')
end=app.find('function defaultSignatureFor(address)',start)
if start<0 or end<0: raise SystemExit('meeting block markers changed')
advanced=r'''function localDateTimeValue(date){const d=new Date(date.getTime()-date.getTimezoneOffset()*60000);return d.toISOString().slice(0,16);}
function icsEscape(v=''){return String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function icsUtc(v){return new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');}
function utf8Base64(text){const bytes=new TextEncoder().encode(text);let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return btoa(binary);}
function meetingProviderLabel(provider){return provider==='teams'?'Microsoft Teams':provider==='zoom'?'Zoom':provider==='google_meet'?'Google Meet':provider==='other'?'Online meeting':'Meeting';}
function recurrenceLabel(rule){return !rule?'Does not repeat':rule==='FREQ=DAILY'?'Daily':rule==='FREQ=WEEKLY'?'Weekly':rule==='FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR'?'Every weekday':rule==='FREQ=MONTHLY'?'Monthly':rule;}
function eventToMeeting(ev,method='REQUEST'){return{id:ev.id,uid:ev.uid,sequence:Number(ev.sequence||0),title:ev.title,start:ev.start_at,end:ev.end_at,timezone:ev.timezone||'Europe/Berlin',allDay:!!ev.all_day,requiredAttendees:arr(ev.required_attendees).join(', '),optionalAttendees:arr(ev.optional_attendees).join(', '),location:ev.location||'',notes:ev.description||'',provider:ev.meeting_provider||'none',joinUrl:ev.meeting_url||'',recurrence:ev.recurrence_rule||'',reminders:arr(ev.reminder_minutes).map(Number),showAs:ev.show_as||'busy',responseRequested:ev.response_requested!==false,organizerAccountId:ev.organizer_account_id||null,status:ev.status||'draft',method};}
function meetingToDb(m){return{user_id:currentUser().id,organizer_account_id:m.organizerAccountId||accountByAddress(defaultFromAddress())?.id||null,title:m.title,start_at:m.start,end_at:m.end,timezone:m.timezone||'Europe/Berlin',all_day:!!m.allDay,required_attendees:splitAddr(m.requiredAttendees),optional_attendees:splitAddr(m.optionalAttendees),location:m.location||null,description:m.notes||null,meeting_provider:m.provider||'none',meeting_url:m.joinUrl||null,recurrence_rule:m.recurrence||null,reminder_minutes:(m.reminders||[15]).map(Number),show_as:m.showAs||'busy',response_requested:m.responseRequested!==false,status:m.status||'draft',uid:m.uid||`${crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}@frankiflow.de`,sequence:Number(m.sequence||0),updated_at:new Date().toISOString()};}
async function persistMeeting(m){const row=meetingToDb(m);let result;if(m.id)result=await supabase.from('frankiflow_mail_events').update(row).eq('id',m.id).select().single();else result=await supabase.from('frankiflow_mail_events').insert(row).select().single();if(result.error){toast(result.error.message,'error');return null;}const stored=result.data;const i=state.events.findIndex(x=>x.id===stored.id);if(i>=0)state.events[i]=stored;else state.events.push(stored);state.events.sort((a,b)=>new Date(a.start_at)-new Date(b.start_at));return stored;}
function allDayIcsDate(v){const d=new Date(v),local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,10).replaceAll('-','');}
function meetingAttachmentPayload(meetingOverride=null){
  const meeting=meetingOverride||state.composer?.meeting;if(!meeting)return null;const d=composerData();const from=d?.fromAddress||state.accounts.find(a=>a.id===meeting.organizerAccountId)?.address||defaultFromAddress();const required=[...new Set(splitAddr(meeting.requiredAttendees||d?.to||'').map(x=>x.toLowerCase()))],optional=[...new Set(splitAddr(meeting.optionalAttendees||d?.cc||'').map(x=>x.toLowerCase()).filter(x=>!required.includes(x)))];const method=meeting.method==='CANCEL'?'CANCEL':'REQUEST',uid=meeting.uid||`${crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}@frankiflow.de`,description=[meeting.notes||'',meeting.joinUrl?`${meetingProviderLabel(meeting.provider)}: ${meeting.joinUrl}`:''].filter(Boolean).join('\n\n');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FrankiFlow Mail//Calendar//EN','CALSCALE:GREGORIAN',`METHOD:${method}`,'BEGIN:VEVENT',`UID:${icsEscape(uid)}`,`DTSTAMP:${icsUtc(new Date())}`,`SEQUENCE:${Number(meeting.sequence||0)}`];
  if(meeting.allDay){lines.push(`DTSTART;VALUE=DATE:${allDayIcsDate(meeting.start)}`,`DTEND;VALUE=DATE:${allDayIcsDate(meeting.end)}`);}else lines.push(`DTSTART:${icsUtc(meeting.start)}`,`DTEND:${icsUtc(meeting.end)}`);
  lines.push(`SUMMARY:${icsEscape(meeting.title)}`,`ORGANIZER:mailto:${icsEscape(from)}`);required.forEach(email=>lines.push(`ATTENDEE;ROLE=REQ-PARTICIPANT;RSVP=${meeting.responseRequested!==false?'TRUE':'FALSE'}:mailto:${icsEscape(email)}`));optional.forEach(email=>lines.push(`ATTENDEE;ROLE=OPT-PARTICIPANT;RSVP=${meeting.responseRequested!==false?'TRUE':'FALSE'}:mailto:${icsEscape(email)}`));if(meeting.location)lines.push(`LOCATION:${icsEscape(meeting.location)}`);if(meeting.joinUrl)lines.push(`URL:${icsEscape(meeting.joinUrl)}`);if(description)lines.push(`DESCRIPTION:${icsEscape(description)}`);if(meeting.recurrence)lines.push(`RRULE:${meeting.recurrence}`);lines.push(meeting.showAs==='free'?'TRANSP:TRANSPARENT':'TRANSP:OPAQUE',method==='CANCEL'?'STATUS:CANCELLED':meeting.showAs==='tentative'?'STATUS:TENTATIVE':'STATUS:CONFIRMED');for(const mins of meeting.reminders||[]){if(Number(mins)<0)continue;lines.push('BEGIN:VALARM',`TRIGGER:-PT${Number(mins)}M`,'ACTION:DISPLAY',`DESCRIPTION:${icsEscape(meeting.title)}`,'END:VALARM');}lines.push('END:VEVENT','END:VCALENDAR');const filename=`${meeting.title||'event'}`.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,60)||'event';return{filename:`${filename}.ics`,content:utf8Base64(lines.join('\r\n')),contentType:`text/calendar; charset=utf-8; method=${method}`};
}
function renderMeetingCard(meeting){const provider=meetingProviderLabel(meeting.provider),when=meeting.allDay?`${new Date(meeting.start).toLocaleDateString([], {dateStyle:'medium'})} · All day`:`${new Date(meeting.start).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})} – ${new Date(meeting.end).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;return`<div class="meeting-card outlook" data-ff-meeting="true"><div class="meeting-card-icon">${icon('event')}</div><div><strong>${esc(meeting.title)}</strong><div><b>When:</b> ${esc(when)} · ${esc(meeting.timezone)}</div>${meeting.location?`<div><b>Where:</b> ${esc(meeting.location)}</div>`:''}${meeting.joinUrl?`<div><b>Online:</b> <a href="${esc(meeting.joinUrl)}" target="_blank">Join ${esc(provider)}</a></div>`:''}${meeting.recurrence?`<div><b>Repeats:</b> ${esc(recurrenceLabel(meeting.recurrence))}</div>`:''}${meeting.notes?`<p>${esc(meeting.notes).replace(/\n/g,'<br>')}</p>`:''}</div></div>`;}
function meetingFormContent(existing,c=null){const base=new Date(Date.now()+60*60000);base.setMinutes(Math.ceil(base.getMinutes()/30)*30,0,0);const finish=new Date(base.getTime()+30*60000),timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Berlin',required=existing?.requiredAttendees||[...new Set([...splitAddr(c?.querySelector('#cTo')?.value||''),...splitAddr(c?.querySelector('#cCc')?.value||'')])].join(', '),reminders=existing?.reminders||[15],provider=existing?.provider||'none';return`<div class="outlook-event-editor"><div class="event-editor-hero">${icon('calendar_month')}<div><strong>Meeting or event</strong><small>Create a complete calendar invitation. Teams, Zoom, Meet and other HTTPS meeting links are supported.</small></div></div><div class="field"><label>Title</label><input id="meetTitle" value="${esc(existing?.title||c?.querySelector('#cSubject')?.value||'') }" placeholder="Add a title"></div><div class="settings-grid two"><div class="field"><label>Organizer</label><select id="meetOrganizer">${state.accounts.map(a=>`<option value="${a.id}" ${existing?.organizerAccountId===a.id?'selected':''}>${esc(a.display_name||'FrankiFlow')} · ${esc(a.address)}</option>`).join('')}</select></div><label class="setting-row compact"><div><strong>All day</strong><small>Use date-only calendar times.</small></div><input id="meetAllDay" type="checkbox" ${existing?.allDay?'checked':''}></label></div><div class="settings-grid two"><div class="field"><label>Starts</label><input id="meetStart" type="datetime-local" value="${esc(existing?localDateTimeValue(new Date(existing.start)):localDateTimeValue(base))}"></div><div class="field"><label>Ends</label><input id="meetEnd" type="datetime-local" value="${esc(existing?localDateTimeValue(new Date(existing.end)):localDateTimeValue(finish))}"></div></div><div class="settings-grid two"><div class="field"><label>Time zone</label><input id="meetTimezone" value="${esc(existing?.timezone||timezone)}"></div><div class="field"><label>Show as</label><select id="meetShowAs"><option value="free">Free</option><option value="working_elsewhere">Working elsewhere</option><option value="tentative">Tentative</option><option value="busy">Busy</option><option value="out_of_office">Out of office</option></select></div></div><div class="field"><label>Required attendees</label><input id="meetRequired" value="${esc(required)}" placeholder="person@example.com, another@example.com"></div><div class="field"><label>Optional attendees</label><input id="meetOptional" value="${esc(existing?.optionalAttendees||'')}" placeholder="optional@example.com"></div><div class="settings-grid two"><div class="field"><label>Repeat</label><select id="meetRecurrence"><option value="">Does not repeat</option><option value="FREQ=DAILY">Daily</option><option value="FREQ=WEEKLY">Weekly</option><option value="FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR">Every weekday</option><option value="FREQ=MONTHLY">Monthly</option></select></div><div class="field"><label>Reminder</label><select id="meetReminder" multiple size="4"><option value="5">5 minutes before</option><option value="10">10 minutes before</option><option value="15">15 minutes before</option><option value="30">30 minutes before</option><option value="60">1 hour before</option><option value="1440">1 day before</option></select></div></div><div class="settings-grid two"><div class="field"><label>Online meeting</label><select id="meetProvider"><option value="none">No online link</option><option value="teams">Microsoft Teams</option><option value="zoom">Zoom</option><option value="google_meet">Google Meet</option><option value="other">Other link</option></select></div><div class="field" id="meetingUrlField"><label>Meeting link</label><input id="meetUrl" type="url" value="${esc(existing?.joinUrl||'')}" placeholder="https://..."></div></div><small class="muted provider-note">Paste an existing Teams, Zoom, Meet or other meeting URL. Automatic creation of provider rooms can be connected later with Microsoft/Zoom OAuth.</small><div class="field"><label>Location</label><input id="meetLocation" value="${esc(existing?.location||'')}" placeholder="Room, office or address"></div><div class="field"><label>Description / agenda</label><textarea id="meetNotes" rows="5" placeholder="Agenda, preparation or event description">${esc(existing?.notes||'')}</textarea></div><label class="setting-row compact"><div><strong>Request responses</strong><small>Ask attendees to RSVP.</small></div><input id="meetResponses" type="checkbox" ${existing?.responseRequested===false?'':'checked'}></label></div>`;}
function readMeetingForm(modal,existing={}){const start=new Date(modal.querySelector('#meetStart').value),end=new Date(modal.querySelector('#meetEnd').value),provider=modal.querySelector('#meetProvider').value,joinUrl=modal.querySelector('#meetUrl').value.trim(),title=modal.querySelector('#meetTitle').value.trim();if(!title){toast('Add an event title','warning');return null;}if(!start.getTime()||!end.getTime()||end<=start){toast('Event end time must be after the start time','warning');return null;}if(provider!=='none'&&!/^https:\/\//i.test(joinUrl)){toast('Add a valid https meeting link','warning');return null;}return{...existing,title,start:start.toISOString(),end:end.toISOString(),timezone:modal.querySelector('#meetTimezone').value.trim()||'Europe/Berlin',allDay:modal.querySelector('#meetAllDay').checked,requiredAttendees:modal.querySelector('#meetRequired').value.trim(),optionalAttendees:modal.querySelector('#meetOptional').value.trim(),organizerAccountId:modal.querySelector('#meetOrganizer').value||null,provider,joinUrl,location:modal.querySelector('#meetLocation').value.trim(),notes:modal.querySelector('#meetNotes').value.trim(),recurrence:modal.querySelector('#meetRecurrence').value,reminders:[...modal.querySelector('#meetReminder').selectedOptions].map(x=>Number(x.value)),showAs:modal.querySelector('#meetShowAs').value,responseRequested:modal.querySelector('#meetResponses').checked,status:existing.status||'draft',method:existing.method||'REQUEST'};}
function prepareMeetingModal(modal,existing){const provider=modal.querySelector('#meetProvider'),urlField=modal.querySelector('#meetingUrlField');provider.value=existing?.provider||'none';modal.querySelector('#meetShowAs').value=existing?.showAs||'busy';modal.querySelector('#meetRecurrence').value=existing?.recurrence||'';[...modal.querySelector('#meetReminder').options].forEach(o=>o.selected=(existing?.reminders||[15]).includes(Number(o.value)));const update=()=>urlField.classList.toggle('hidden',provider.value==='none');provider.onchange=update;update();}
function attachMeetingToComposer(meeting){const c=state.composer?.el;if(!c)return;state.composer.meeting=meeting;const req=splitAddr(meeting.requiredAttendees),opt=splitAddr(meeting.optionalAttendees);if(req.length&&!c.querySelector('#cTo').value.trim())c.querySelector('#cTo').value=req.join(', ');if(opt.length&&!c.querySelector('#cCc').value.trim())c.querySelector('#cCc').value=opt.join(', ');if(!c.querySelector('#cSubject').value.trim())c.querySelector('#cSubject').value=(meeting.method==='CANCEL'?'Cancelled: ':'')+meeting.title;const editor=c.querySelector('#cEditor');editor.querySelectorAll('[data-ff-meeting]').forEach(x=>x.remove());editor.insertAdjacentHTML('afterbegin',`${renderMeetingCard(meeting)}<br>`);scheduleAutosave();}
function openMeetingScheduler(seed=null){const c=state.composer?.el||null,existing=seed||state.composer?.meeting||null;openModal(existing?.id?'Edit event':'New meeting / event',meetingFormContent(existing,c),async modal=>{const meeting=readMeetingForm(modal,existing||{});if(!meeting)return;const stored=await persistMeeting({...meeting,status:meeting.status==='sent'?'sent':'draft'});if(!stored)return;const normalized=eventToMeeting(stored,meeting.method||'REQUEST');if(c)attachMeetingToComposer(normalized);modal.closest('.modal-backdrop').remove();toast(c?'Calendar invitation attached':'Event saved','event');},modal=>prepareMeetingModal(modal,existing));}
function eventManagerRow(ev){const m=eventToMeeting(ev),when=m.allDay?new Date(m.start).toLocaleDateString([], {dateStyle:'medium'}):new Date(m.start).toLocaleString([], {dateStyle:'medium',timeStyle:'short'});return`<div class="event-manager-row" data-event-id="${ev.id}"><div class="event-date-badge"><span>${new Date(m.start).toLocaleDateString([], {month:'short'})}</span><b>${new Date(m.start).getDate()}</b></div><div class="event-manager-main"><strong>${esc(m.title)}</strong><small>${esc(when)} · ${esc(m.timezone)}${m.joinUrl?` · ${esc(meetingProviderLabel(m.provider))}`:''}</small><span class="event-status ${esc(ev.status)}">${esc(ev.status)}</span></div><button class="icon-btn" data-event-edit="${ev.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-event-send="${ev.id}" title="Send invitation/update">${icon('forward_to_inbox')}</button>${ev.status!=='cancelled'?`<button class="icon-btn danger" data-event-cancel="${ev.id}" title="Cancel event">${icon('event_busy')}</button>`:''}</div>`;}
function openEventInComposer(ev,method='REQUEST'){const meeting=eventToMeeting(ev,method);if(method==='REQUEST'&&ev.status==='sent')meeting.sequence=Number(ev.sequence||0)+1;if(method==='CANCEL')meeting.sequence=Number(ev.sequence||0)+1;openComposer({fromAddress:state.accounts.find(a=>a.id===ev.organizer_account_id)?.address||defaultFromAddress(),to:arr(ev.required_attendees).join(', '),cc:arr(ev.optional_attendees).join(', '),subject:(method==='CANCEL'?'Cancelled: ':'')+ev.title});attachMeetingToComposer(meeting);}
async function cancelEvent(ev){if(!confirm(`Cancel “${ev.title}” and prepare a cancellation invitation?`))return;const sequence=Number(ev.sequence||0)+1;const {data,error}=await supabase.from('frankiflow_mail_events').update({status:'cancelled',sequence,updated_at:new Date().toISOString()}).eq('id',ev.id).select().single();if(error)return toast(error.message,'error');const i=state.events.findIndex(x=>x.id===ev.id);if(i>=0)state.events[i]=data;openEventInComposer(data,'CANCEL');document.querySelector('.modal-backdrop')?.remove();toast('Cancellation invitation prepared','event_busy');}
function openEventManager(){const upcoming=state.events.filter(e=>new Date(e.end_at)>=new Date(Date.now()-86400000)).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at));const content=`<div class="event-manager"><div class="event-manager-toolbar"><div><strong>Calendar & events</strong><small>${upcoming.length} upcoming / recent event${upcoming.length===1?'':'s'}</small></div><button class="btn-primary" id="newEventBtn">${icon('add')} New event</button></div><div class="event-manager-list">${upcoming.map(eventManagerRow).join('')||'<div class="empty-event-list">No events yet. Create a meeting or event to get started.</div>'}</div></div>`;openModal('Calendar & events',content,null,modal=>{modal.querySelector('#newEventBtn').onclick=()=>openMeetingScheduler();modal.querySelectorAll('[data-event-edit]').forEach(b=>b.onclick=()=>openMeetingScheduler(eventToMeeting(state.events.find(e=>e.id===b.dataset.eventEdit))));modal.querySelectorAll('[data-event-send]').forEach(b=>b.onclick=()=>{const ev=state.events.find(e=>e.id===b.dataset.eventSend);if(ev){openEventInComposer(ev,'REQUEST');modal.closest('.modal-backdrop').remove();}});modal.querySelectorAll('[data-event-cancel]').forEach(b=>b.onclick=()=>{const ev=state.events.find(e=>e.id===b.dataset.eventCancel);if(ev)cancelEvent(ev);});});}
'''
app=app[:start]+advanced+app[end:]

# Mark sent events/updates after successful mail send.
