new_ok="if(ok){if(state.composer.meeting?.id){const m=state.composer.meeting;const status=m.method==='CANCEL'?'cancelled':'sent';const sequence=Number(m.sequence||0);await supabase.from('frankiflow_mail_events').update({status,sequence,updated_at:new Date().toISOString()}).eq('id',m.id);const ev=state.events.find(x=>x.id===m.id);if(ev){ev.status=status;ev.sequence=sequence;}}state.composer.el.remove();state.composer=null;}else{"
if old_ok not in app: raise SystemExit('sendComposer success marker changed')
