app=app.replace(wire,wire_new,1)

# Add calendar/events to mobile More menu.
app=app.replace("showPopover(mobileMore,[['Settings','settings',openSettings],['Refresh','refresh',()=>loadAll(true)],['Sign out','logout',()=>supabase.auth.signOut()]])", "showPopover(mobileMore,[['Calendar & events','calendar_month',openEventManager],['Settings','settings',openSettings],['Refresh','refresh',()=>loadAll(true)],['Sign out','logout',()=>supabase.auth.signOut()]])",1)

# CSS.
css += r'''

/* Outlook-style Calendar & Events */
.outlook-event-editor{display:grid;gap:13px}.event-editor-hero{display:flex;align-items:center;gap:12px;padding:13px;border-radius:14px;background:linear-gradient(135deg,var(--brand-soft),var(--surface-2));border:1px solid var(--line)}.event-editor-hero>.material-symbols-rounded{font-size:29px;color:var(--brand-2)}.event-editor-hero strong,.event-editor-hero small{display:block}.event-editor-hero small{margin-top:3px;color:var(--muted)}.provider-note{margin-top:-7px}.setting-row.compact{min-height:54px;border:1px solid var(--line);border-radius:12px;padding:8px 10px;background:var(--surface)}.meeting-card.outlook{display:flex;gap:12px;padding:14px;border-radius:14px;border-left:4px solid var(--brand-2);background:var(--brand-soft);margin-bottom:14px}.meeting-card-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:10px;background:var(--surface)}.meeting-card.outlook>div:last-child{min-width:0}.meeting-card.outlook strong{display:block;font-size:14px;margin-bottom:5px}.meeting-card.outlook div,.meeting-card.outlook p{font-size:12px;line-height:1.55}.event-manager{display:grid;gap:14px}.event-manager-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px}.event-manager-toolbar strong,.event-manager-toolbar small{display:block}.event-manager-toolbar small{color:var(--muted);margin-top:2px}.event-manager-list{display:grid;gap:8px}.event-manager-row{display:grid;grid-template-columns:52px minmax(0,1fr) auto auto auto;align-items:center;gap:8px;border:1px solid var(--line);border-radius:14px;padding:9px;background:var(--surface)}.event-date-badge{width:48px;height:48px;border-radius:11px;background:var(--brand-soft);display:grid;place-items:center;align-content:center}.event-date-badge span{font-size:9px;text-transform:uppercase;color:var(--brand-2);font-weight:800}.event-date-badge b{font-size:18px}.event-manager-main{min-width:0}.event-manager-main strong,.event-manager-main small{display:block}.event-manager-main small{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:3px}.event-status{display:inline-flex;margin-top:5px;padding:2px 7px;border-radius:999px;background:var(--surface-3);font-size:9px;text-transform:uppercase;font-weight:800}.event-status.sent{background:color-mix(in srgb,var(--success) 15%,var(--surface));color:var(--success)}.event-status.cancelled{background:color-mix(in srgb,var(--danger) 12%,var(--surface));color:var(--danger)}.empty-event-list{padding:28px;text-align:center;border:1px dashed var(--line);border-radius:14px;color:var(--muted)}.sender-identity-card{display:flex;align-items:center;gap:13px;padding:12px;border:1px solid var(--line);border-radius:14px;background:var(--surface);margin-bottom:10px}.sender-identity-card img{width:58px;height:58px;object-fit:contain;border-radius:12px;background:#fff;padding:5px}.sender-identity-card strong,.sender-identity-card small{display:block}.sender-identity-card small{margin-top:4px;color:var(--muted);line-height:1.45}.identity-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.identity-tags span{font-size:9px;font-weight:800;padding:3px 7px;border-radius:999px;background:var(--brand-soft);color:var(--brand-2)}.identity-guide p{line-height:1.65}.modal:has(.outlook-event-editor),.modal:has(.event-manager){width:min(820px,calc(100vw - 28px));max-height:min(90vh,920px)}.modal:has(.outlook-event-editor) .modal-body,.modal:has(.event-manager) .modal-body{overflow:auto}@media(max-width:640px){.event-manager-row{grid-template-columns:46px minmax(0,1fr) auto}.event-manager-row>[data-event-send],.event-manager-row>[data-event-cancel]{grid-row:2}.event-manager-row>[data-event-send]{grid-column:2}.event-manager-row>[data-event-cancel]{grid-column:3}.event-manager-toolbar{align-items:stretch;flex-direction:column}.event-manager-toolbar .btn-primary{justify-content:center}.sender-identity-card{align-items:flex-start}.sender-identity-card img{width:48px;height:48px}}
'''

# Force installed PWA to update while retaining push handlers.
sw=re.sub(r"const CACHE = 'frankiflow-mail-dev-v\d+';", "const CACHE = 'frankiflow-mail-dev-v11';", sw, count=1)

app_path.write_text(app)
css_path.write_text(css)
sw_path.write_text(sw)
